import{z as s,x as B,o,c as i,q as d,j as r,D as a,d as t,s as E,S as c}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"整数溢出检测","description":"","frontmatter":{"title":"整数溢出检测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/overflow-detect.md","filePath":"cs/overflow-detect.md","lastUpdated":1791063341000}'),l={name:"cs/overflow-detect.md"};function A(C,e,p,_,D,h){const n=B("Mermaid");return o(),i("div",null,[e[2]||(e[2]=d('<h1 id="整数溢出检测" tabindex="-1">整数溢出检测 <a class="header-anchor" href="#整数溢出检测" aria-label="Permalink to &quot;整数溢出检测&quot;">​</a></h1><div class="epigraph"><p>补码加减的溢出不是最高位进位本身，而是进位入与进位出是否一致；无符号则看那一位进位。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/fixed-point-dsp">上一课</a>把定点 MAC 写成宽累加再截位，但没说截位时如何知道「已经不能表示」。组成课的<a href="/cs/adder-cla">加法器</a>点过溢出接线，ALU 课也留了旗标口。缺口是把检测收成可用的硬件条件：有符号与无符号不同，乘除另算，供下一课饱和与后课 HDL 当控制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 位补码可表示 \\([-2^{n-1},2^{n-1}-1]\\)。两正数相加得负，或两负数相加得正，即溢出：等价于最高位的进位入 \\(c_{n-1}\\) 与进位出 \\(c_n\\) 异或。无符号溢出就是 \\(c_n\\)。减法通过加反码走同一对进位。缺口不是再证补码表示，而是：<strong>旗标从哪根线来</strong>，以及 RISC-V 整数 <code>add</code> 默认不陷阱、软件要用 <code>add</code>/<code>sltu</code> 组合或分支去查。</p><p>定点 DSP 的累加器若宽于输出，溢出发生在<strong>截回输出宽度</strong>时，不是发生在宽加本身。</p><h3 id="进位不是溢出" tabindex="-1">进位不是溢出 <a class="header-anchor" href="#进位不是溢出" aria-label="Permalink to &quot;进位不是溢出&quot;">​</a></h3><p>无符号里进位≈溢出；有符号里 \\(c_n=1\\) 仍可能合法（例如 \\((-1)+(-1)\\) 得 \\(-2\\)，\\(c_n=1\\) 但未溢出）。把 FLAGS 的 Carry 与 Overflow 混用，条件跳会错。x86 的 <code>OF</code>/<code>CF</code> 分家，后课 ISA 对照会再看见；本课先钉布尔。</p><p><span class="marginnote">Harris 用 \\(c_n\\oplus c_{n-1}\\)。Patterson/Hennessy 强调 RISC-V 不因溢出陷入。本课不把 C 语言的未定义行为当硬件语义：硬件总给出模 \\(2^n\\) 的比特，检测是额外的位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加法器已有各位进位。引出 <code>V = c_n XOR c_{n-1}</code>（有符号），<code>C = c_n</code>（无符号）。乘：积的高半是否等于低半的符号扩展（有符号）或全 0（无符号）。除：除零与有符号 <code>min/-1</code>。FPU 的 overflow 是指数饱和，不要接到这对进位。</p>',11)),(o(),r(c,null,{default:a(()=>[E(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22CLA%20%E5%90%84%E4%BD%8D%E8%BF%9B%E4%BD%8D%22%5D%20--%3E%20V%5B%22c_n%20XOR%20c_%7Bn-1%7D%20%E6%9C%89%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20ADD%20--%3E%20C%5B%22c_n%20%E6%97%A0%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20V%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A5%B1%E5%92%8C%22%5D%0A%20%20C%20--%3E%20LATER%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d('<p>软件：RISC-V 用 <code>add t0,a0,a1</code> 再比较符号与操作数关系，或用更宽临时寄存器。硬件可选 <code>add</code> 写 <code>V</code> 到标志——ISA 选择。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课饱和运算把 <code>V</code>/<code>C</code> 变成「钉在最大/最小可表示数」，而不是环绕。浮点<a href="/cs/fp-exceptions">异常</a>五位与这里的 <code>V</code> 分家：一个是 754 状态，一个是整数进位。后课 Verilog 里这两个位只是组合输出，不要用阻塞赋值在时钟边沿「补算」溢出，那是 HDL 课的坑。</p><p>同一组比特，两种解读下溢出结论可以不同：判定只看进位对，不看「结果像不像溢出」。用 8 位把三种情形摆出来，<code>V</code> 与 <code>C</code> 各管各的。</p>',4)),(o(),r(c,null,{default:a(()=>[E(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20EX1%5B%22%E6%9C%89%E7%AC%A6%E5%8F%B7%208%20%E4%BD%8D%EF%BC%9A100%20%2B%2050%22%5D%20--%3E%20B1%5B%22%E6%AF%94%E7%89%B9%E7%BB%93%E6%9E%9C%200x96%EF%BC%8C%E8%AF%BB%E4%BD%9C%20-106%22%5D%0A%20%20B1%20--%3E%20V1%5B%22%E4%B8%A4%E6%AD%A3%E5%BE%97%E8%B4%9F%EF%BC%9AV%20%3D%201%EF%BC%8C%E6%9C%89%E7%AC%A6%E5%8F%B7%E6%BA%A2%E5%87%BA%22%5D%0A%20%20EX2%5B%22%E6%9C%89%E7%AC%A6%E5%8F%B7%208%20%E4%BD%8D%EF%BC%9A(-1)%20%2B%20(-1)%22%5D%20--%3E%20B2%5B%22%E6%AF%94%E7%89%B9%E7%BB%93%E6%9E%9C%200xFE%EF%BC%8C%E8%AF%BB%E4%BD%9C%20-2%22%5D%0A%20%20B2%20--%3E%20V2%5B%22%E4%B8%A4%E8%B4%9F%E5%BE%97%E8%B4%9F%EF%BC%9AV%20%3D%200%EF%BC%8C%E5%90%88%E6%B3%95%22%5D%0A%20%20EX3%5B%22%E6%97%A0%E7%AC%A6%E5%8F%B7%208%20%E4%BD%8D%EF%BC%9A200%20%2B%20100%22%5D%20--%3E%20B3%5B%22%E6%AF%94%E7%89%B9%E7%BB%93%E6%9E%9C%2044%EF%BC%8C%E8%BF%9B%E4%BD%8D%E5%87%BA%E4%B8%BA%201%22%5D%0A%20%20B3%20--%3E%20U1%5B%22C%20%3D%201%EF%BC%8C%E6%97%A0%E7%AC%A6%E5%8F%B7%E6%BA%A2%E5%87%BA%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<p><span class="marginnote">数字实例：8 位补码上限 127。127+1 的比特是 0x80，读回来恰是 -128——最大正数加一步跳到最小负数，这是 \\(V=1\\) 最经典的样子；无符号那边 255+1 绕回 0 并立起进位 \\(C\\)。</span></p><p><span class="marginnote">常见误区：初学者容易把「有进位出」当成「有符号溢出」。\\((-1)+(-1)\\) 就有进位出但结果 -2 完全合法；这是两根独立的旗标线，x86 干脆分成 OF 与 CF 两个标志，条件跳转各用各的。</span></p><p><span class="marginnote">为什么重要：定点 DSP 的宽累加器加几百次都不溢出，但最后截回 16 位输出时若不查一次 <code>V</code>，前面攒下的高位精度就无声丢掉——检测必须挂在截位那一瞬，而不是宽加本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定溢出必须陷阱（x86 <code>INTO</code> 是另一风格）。不讨论 saturating SIMD 指令表。不把密码学里的恒定时间溢出处理写成安全课。</p><p>后课默认：有符号溢出看最高两位进位异或；无符号看进位出；默认递送环绕结果加可选旗标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定点截位需要知道是否溢出；检测从加法器进位来。</li><li>有符号：<code>V=c_n⊕c_{n-1}</code>；无符号：<code>C=c_n</code>。</li><li>RISC-V <code>add</code> 不自动陷入；饱和是下一课的用法。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const f=s(l,[["render",A]]);export{m as __pageData,f as default};
